CREATE OR REPLACE FORCE EDITIONABLE VIEW "PPPT"."COMP_PERSONAL2" ("IDCOMPARACION", "IDPERSONAL", "NOMBRE", "IDPUESTO0", "IDPUESTO1", "IDPUESTO2", "IDPUESTO3", "IDPUESTO4", "IDPUESTO5", "IDPUESTO6", "IDPUESTO7", "IDPUESTO8", "IDPUESTO9") AS 
  SELECT ComparacionPersonal.IdComparacion, Personal.IdPersonal, Personal.Nombre, ComparacionPersonal.IdPuesto0, ComparacionPersonal.IdPuesto1, ComparacionPersonal.IdPuesto2, ComparacionPersonal.IdPuesto3, ComparacionPersonal.IdPuesto4, ComparacionPersonal.IdPuesto5, ComparacionPersonal.IdPuesto6, ComparacionPersonal.IdPuesto7, ComparacionPersonal.IdPuesto8, ComparacionPersonal.IdPuesto9 FROM ComparacionPersonal INNER JOIN Personal ON ComparacionPersonal.IdPersonal = Personal.IdPersonal;
